    LARGE_INTEGER size{};Win(GetFileSizeEx(output.h,&size)!=FALSE,"Read utility log size");Seek(output.h,0);auto data=Read(output.h,static_cast<size_t>(std::min(size.QuadPart,65536LL)));std::wstring text;
    if(data.size()>=4&&((data[0]==0xff&&data[1]==0xfe)||(data[1]==0&&data[3]==0))){size_t begin=data[0]==0xff?2:0;text.assign(reinterpret_cast<const wchar_t*>(data.data()+begin),(data.size()-begin)/2);}
