    try{do{try{std::wstring path=name;while(!path.empty()&&path.back()==L'\\')path.pop_back();auto h=File(path);auto data=Ioctl(h->h,IOCTL_VOLUME_GET_VOLUME_DISK_EXTENTS);if(data.size()<sizeof(VOLUME_DISK_EXTENTS))continue;auto* e=reinterpret_cast<VOLUME_DISK_EXTENTS*>(data.data());if(e->NumberOfDiskExtents!=1||e->Extents[0].DiskNumber!=static_cast<DWORD>(target))continue;auto part=Ioctl(h->h,IOCTL_DISK_GET_PARTITION_INFO_EX);if(part.size()<sizeof(PARTITION_INFORMATION_EX))continue;auto* p=reinterpret_cast<PARTITION_INFORMATION_EX*>(part.data());GUID efi={0xc12a7328,0xf81f,0x11d2,{0xba,0x4b,0x00,0xa0,0xc9,0x3e,0xc9,0x3b}};if(p->PartitionStyle==PARTITION_STYLE_GPT&&IsEqualGUID(p->Gpt.PartitionType,efi)){efiVolume=name;efiCount++;}else if(p->PartitionStyle==PARTITION_STYLE_GPT&&IsEqualGUID(p->Gpt.PartitionType,recoveryType)&&fs::exists(fs::path(name)/L"Recovery"/L"WindowsRE"/L"Winre.wim")){NoLinks(fs::path(name)/L"Recovery"/L"WindowsRE"/L"Winre.wim");recoveryVolumes.emplace_back(name);}}catch(const std::runtime_error&){}}while(FindNextVolumeW(search,name,1024));FindVolumeClose(search);}catch(...){FindVolumeClose(search);throw;}
